{
  "dispositions": {
    "n-hc09al": {
      "disposition": "board",
      "reason": "Supported condition regarding approximate timestamps in handwritten logs.",
      "targetKey": null,
      "question": "",
      "proposition": {"type":"condition","label":"Handwritten records are approximate unless stated otherwise.","detail":"Shift log entries like 'About 10:07' lack precise timestamps, introducing uncertainty about exact restoration time and response duration.","assessmentKind":"observation","sourceIds":["d838e866-dc34-4814-8dad-3b97d0353f05#1"],"claimIds":[]}
    },
    "n-aag550": {
      "disposition": "board",
      "reason": "Supported condition regarding RHOB process area instrument air supply and alarm thresholds.",
      "targetKey": null,
      "question": "",
      "proposition": {"type":"condition","label":"RHOB process area receives instrument air from Utilities gallery via receiving header H-R.","detail":"Normal operation involves pressure monitoring at P-R (receiving station) and upstream P-U. Alarm AL-44 monitors low-pressure condition below 4.5 bar.","assessmentKind":"observation","sourceIds":["b678a928-a8d2-472d-bc03-2e1a3dc411e6#1"],"claimIds":[]}
    },
    "n-1sd8vsk": {
      "disposition": "board",
      "reason": "Supported condition regarding limitations of pressure extract IA-P01.",
      "targetKey": null,
      "question": "",
      "proposition": {"type":"condition","label":"Pressure extract IA-P01 provides sampled values only (not continuous) and excludes data from all locations or valve states.","detail":"Export covers P-U, P-R, C-11 RUN but lacks full waveform coverage. Cannot confirm simultaneous events at other points like North gallery without additional evidence.","assessmentKind":"observation","sourceIds":["fcd254db-75b3-4a9d-abec-44c5b6a9b34e#1"],"claimIds":[]}
    },
    "n-177jnpq": {
      "disposition": "board",
      "reason": "Supported condition regarding point register IA-P02 limitations.",
      "targetKey": null,
      "question": "",
      "proposition": {"type":"condition","label":"Point register IA-P02 does not establish state of any distribution valve.","detail":"Register maps signals (P-U, P-R, C-11 RUN, AL-44) but explicitly states it cannot prove supply disturbance appearance in sample export or valve positions.","assessmentKind":"observation","sourceIds":["da0260c0-7d49-43e8-b074-da2a14c7d59c#1"],"claimIds":[]}
    }
  },
  "decision": {
    "summary": "Consolidated four supported condition propositions from the evidence packet. No merges were required as all keys are distinct and refer to different aspects of system behavior or record limitations.",
    "evidenceUsed": ["d838e866-dc34-4814-8dad-3b97d0353f05#1", "b678a928-a8d2-472d-bc03-2e1a3dc411e6#1", "fcd254db-75b3-4a9d-abec-44c5b6a9b34e#1", "da0260c0-7d49-43e8-b074-da2a14c7d59c#1"],
    "unknowns": ["Exact cause of pressure drop at P-R (leak vs upstream closure)", "Whether valve M-101/M-102 was closed", "If simultaneous low-pressure occurred elsewhere"],
    "alternatives": [],
    "confidence": 1.0
  }
}
